messages.content:
Berikut manifest game edukasi Endless Runner tentang tokoh proklamasi dan Sumpah Pemuda sesuai PRD yang disetujui. Fatmawati saya masukkan sebagai item kategori "bukan-proklamator" agar miskonsepsi teruji lewat mekanik pengelompokan.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "proklamasi-sumpahpemuda-run", title: "Proklamasi & Sumpah Pemuda Run", seed: "proklamasi-01",
  theme: { preset: "clean-modern" },

  learning: {
    subject: "Sejarah Indonesia",
    concept: "Membedakan tokoh proklamasi dan tokoh Sumpah Pemuda berdasarkan perannya",
    objectives: ["Mengelompokkan tokoh sesuai peran bakunya dalam peristiwa sejarah"],
    misconceptions: ["Fatmawati dianggap proklamator karena menjahit bendera pusaka"],
    mode: "category",
    categories: [
      { id: "proklamator", label: "Proklamator", color: "#2F80ED" },
      { id: "perumus-sumpah-pemuda", label: "Perumus Sumpah Pemuda", color: "#3FA34D" },
      { id: "bukan-proklamator", label: "Bukan Proklamator", color: "#E5484D" }
    ],
    items: [
      { id: "soekarno", label: "Soekarno", category: "proklamator", explain: "Membacakan teks proklamasi pada 17 Agustus 1945." },
      { id: "mohammad-hatta", label: "Mohammad Hatta", category: "proklamator", explain: "Mendampingi dan turut menandatangani teks proklamasi." },
      { id: "achmad-soebardjo", label: "Achmad Soebardjo", category: "proklamator", explain: "Turut menyusun naskah proklamasi di rumah Laksamana Maeda." },
      { id: "moehammad-yamin", label: "Moehammad Yamin", category: "perumus-sumpah-pemuda", explain: "Mengusulkan rumusan Sumpah Pemuda dalam Kongres Pemuda II." },
      { id: "soegondo", label: "Soegondo Djojopoespito", category: "perumus-sumpah-pemuda", explain: "Ketua Kongres Pemuda II yang memimpin perumusan." },
      { id: "wr-supratman", label: "Wage Rudolf Supratman", category: "perumus-sumpah-pemuda", explain: "Menciptakan lagu Indonesia Raya untuk Kongres Pemuda II." },
      { id: "fatmawati", label: "Fatmawati", category: "bukan-proklamator", explain: "Menjahit bendera pusaka, bukan penanda tangan teks proklamasi." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 5, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 300, maxSpeed: 600, accel: 4 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "tiang", w: 70, h: 70, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 20, speed: 20 }
  }
});
// END_OF_MANIFEST
```
